// src/components/layout/MainLayout.jsx
const MainLayout = () => {
  const { heroData } = useUI();

  return (
    <div
      className="layout-wrapper"
      style={{
        display: "flex",
        flexDirection: "column",
        height: "100vh", // 鎖定視窗高度
      }}
    >
      <Hero {...heroData} />

      <Box
        component="main"
        sx={{
          flex: 1,
          display: "flex",
          justifyContent: "center", // 讓卡片置中
          alignItems: "center", // 讓卡片在 Hero 和 Footer 之間置中
          overflow: "hidden", // 關鍵：隱藏溢出
          width: "100%",
          backgroundColor: "#f5f5f5",
        }}
      >
        {/* 在這裡統一卡片外殼 */}
        <div className={styles.interactiveCard}>
          <Outlet />
        </div>
      </Box>

      <Footer />
    </div>
  );
};

export default MainLayout;
